import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), gap = nextInt();
        // pack (height, index) into one long so sorting is by height then index
        long[] r = new long[n];
        for (int i = 0; i < n; i++) r[i] = nextLong() << 20 | i;
        Arrays.sort(r);
        long mask = (1 << 20) - 1;
        // monotonic deques over the sorted window: smallest and largest original index
        int[] mn = new int[n], mx = new int[n];
        int mnH = 0, mnT = 0, mxH = 0, mxT = 0, left = 0;
        long answer = Long.MAX_VALUE;
        for (int right = 0; right < n; right++) {
            long idx = r[right] & mask;
            while (mnT > mnH && (r[mn[mnT - 1]] & mask) >= idx) mnT--;
            while (mxT > mxH && (r[mx[mxT - 1]] & mask) <= idx) mxT--;
            mn[mnT++] = right;
            mx[mxT++] = right;
            while ((r[mx[mxH]] & mask) - (r[mn[mnH]] & mask) >= gap) {
                answer = Math.min(answer, (r[right] >> 20) - (r[left] >> 20));
                if (mn[mnH] == left) mnH++;
                if (mx[mxH] == left) mxH++;
                left++;
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n, gap := readInt(), readInt()
	// pack (height, index) into one int so sorting is by height then index
	r := make([]int, n)
	for i := range r {
		r[i] = readInt()<<20 | i
	}
	sort.Ints(r)
	const mask = 1<<20 - 1
	// monotonic deques over the sorted window: smallest and largest original index
	mn := make([]int, 0, n)
	mx := make([]int, 0, n)
	mnH, mxH, left := 0, 0, 0
	answer := -1
	for right := 0; right < n; right++ {
		idx := r[right] & mask
		for len(mn) > mnH && r[mn[len(mn)-1]]&mask >= idx {
			mn = mn[:len(mn)-1]
		}
		for len(mx) > mxH && r[mx[len(mx)-1]]&mask <= idx {
			mx = mx[:len(mx)-1]
		}
		mn = append(mn, right)
		mx = append(mx, right)
		for r[mx[mxH]]&mask-r[mn[mnH]]&mask >= gap {
			d := r[right]>>20 - r[left]>>20
			if answer < 0 || d < answer {
				answer = d
			}
			if mn[mnH] == left {
				mnH++
			}
			if mx[mxH] == left {
				mxH++
			}
			left++
		}
	}
	fmt.Println(answer)
}
